// Index entry: index_header.go[CHD7AM]
//
// This file carries the shared entry of the `aoci index header` command group and Show.
//
// From 0.2.0 the Legacy layout is read-only: Endpoint Draft, Diff, and Apply retired with the Legacy authoring surface,
// and the Meta of Volumes v1 is generated by init and rewritten by governance transactions, with no manual Header write command.
package cli

import (
	"fmt"

	"github.com/aoci-spec/aoci-code/internal/ledger"
	"github.com/aoci-spec/aoci-code/internal/mcptools"
	"github.com/spf13/cobra"
)

// newIndexHeaderCmd builds the `aoci index header` subcommand group.
func newIndexHeaderCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "header",
		Short: cliMessage("cli.short.index_header"),
	}
	cmd.AddCommand(newHeaderShowCmd())
	return cmd
}

// newHeaderShowCmd builds `aoci index header show`.
//
// It shares mcptools.BuildHeaderText with the MCP aoci_header, so no second header reading logic appears.
func newHeaderShowCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "show",
		Short: cliMessage("cli.short.index_header_show"),
		RunE: func(
			cmd *cobra.Command,
			args []string,
		) error {
			repoRoot, err := resolveRepoRoot()
			if err != nil {
				return &ExitError{
					Code: ExitConfig,
					Err:  err,
				}
			}

			header, failure := mcptools.BuildHeaderText(
				repoRoot,
				ledger.SourceHuman,
			)
			if failure != nil {
				return &ExitError{
					Code: ExitConfig,
					Err: fmt.Errorf("%s", cliMessage(
						"header.show.failed",
						failure.Code,
						localeSafeCLIDetail(failure.Msg),
						localeSafeCLIDetail(failure.Hint),
					)),
				}
			}

			output := cmd.OutOrStdout()
			if header == "" {
				fmt.Fprintln(output, cliMessage("header.show.empty"))
				return nil
			}

			fmt.Fprint(output, header)
			return nil
		},
	}
}
